import icontract


def is_upper_case(c: str) -> bool:
    return 'A' <= c <= 'Z'


def shift32(c: str) -> str:
    return chr(ord(c) + 32)


@icontract.ensure(lambda s, result: len(result) == len(s))
@icontract.ensure(lambda s, result: len(result) == len(s) and all(
    (result[i] == shift32(s[i])) if is_upper_case(s[i]) else (result[i] == s[i]) for i in range(len(s))))
def toLowercase(s: str) -> str:
    chars = []
    for c in s:
        if 'A' <= c <= 'Z':
            chars.append(chr(ord(c) + 32))
        else:
            chars.append(c)
    return ''.join(chars)
